		INSERT INTO "inventory_warehouses" ("id", "code", "name", "warehouse_role", "address", "manager_user_id", "incoming_flow", "outgoing_flow", "status", "notes", "org_id", "is_archived", "created_at", "updated_at", "etag") VALUES
		('01K5INV00000000000WH000001', 'WH-CENTRAL', 'Central Distribution Centre', 'central', '12 Nguyen Van Linh, District 7, Ho Chi Minh City', '01JZQFFDKY8T4JB8R6NSY1331J', 'three_step', 'three_step', 'active', 'Receives all imports; three-step in (receive/quality/stock) and out (pick/pack/ship).', '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV00000000000WH000002', 'WH-NORTH', 'Northern Regional Warehouse', 'sub', '45 Pham Van Dong, Bac Tu Liem, Ha Noi', '01JWNXT3EY7FG47VDJTEPTDC98', 'two_step', 'two_step', 'active', 'Replenished from the central DC.', '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV00000000000WH000003', 'WH-SOUTH', 'Southern Regional Warehouse', 'sub', '88 Vo Van Kiet, District 5, Ho Chi Minh City', '01JZQFZFK6GM2D5X6MYHWH6FND', 'one_step', 'two_step', 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV00000000000WH000004', 'WH-POS-Q1', 'District 1 Store Backroom', 'pos', '200 Le Loi, District 1, Ho Chi Minh City', NULL, 'one_step', 'one_step', 'active', 'Point-of-sale backroom; single-step in and out.', '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV00000000000WH000005', 'WH-3PL', 'Third-party Overflow Site', 'other', 'Lot C3, VSIP II, Binh Duong', NULL, 'one_step', 'one_step', 'suspended', 'Contract paused; kept for historical stock only.', '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NOW(), (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV00000000000WH000006', 'WH-OLD', 'Decommissioned Depot', 'other', NULL, NULL, 'one_step', 'one_step', 'suspended', 'Archived: closed in 2025.', '01JWNY20G23KD4RV5VWYABQYHD', TRUE, NOW(), NOW(), (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV00000000000WH000007', 'WH-TECH-MAIN', 'Tech Solutions Main Store', 'central', '9 Duy Tan, Cau Giay, Ha Noi', NULL, 'two_step', 'one_step', 'active', NULL, '01K1H7M2K9VW3P5R7XQJY2C1Z9', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text)
