		('01K5INV000000000WHSUPPLY02', '01K5INV00000000000WH000003', '01K5INV00000000000WH000002', 2, FALSE, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000WHSUPPLY03', '01K5INV00000000000WH000001', '01K5INV00000000000WH000003', 1, TRUE, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000WHSUPPLY04', '01K5INV00000000000WH000003', '01K5INV00000000000WH000004', 1, TRUE, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000WHSUPPLY05', '01K5INV00000000000WH000001', '01K5INV00000000000WH000005', 3, FALSE, '01JWNY20G23KD4RV5VWYABQYHD', TRUE, NOW(), NOW(), (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text)
		ON CONFLICT ("id") DO NOTHING;

		-- Locations. Every location_usage value is represented. The physical tree under each
		-- warehouse is: root (managed by the warehouse, where its stock lives) -> zone -> bin, with
		-- canonical_name, warehouse_id and hierarchy_depth kept consistent with parent_location_id. The virtual locations (vendor, customer, transit,
		-- scrap, inventory_loss) carry no warehouse_id and are the counterparties every receipt,
		-- delivery, scrap and count adjustment moves against.
		INSERT INTO "inventory_locations" ("id", "name", "canonical_name", "location_usage", "purpose", "warehouse_id", "parent_location_id", "hierarchy_depth", "barcode", "storage_category_id", "removal_strategy", "is_replenishment_destination", "is_system_generated", "status", "description", "org_id", "is_archived", "created_at", "updated_at", "managed_by_type", "managed_by_id", "etag") VALUES
		-- Virtual counterparty locations, shared across warehouses.
		('01K5INV000000000000LOC0001', 'Vendors', 'Vendors', 'vendor', NULL, NULL, NULL, 0, NULL, NULL, NULL, FALSE, TRUE, 'active', 'Goods originate here on a receipt', '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, 'system', NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000000LOC0002', 'Customers', 'Customers', 'customer', NULL, NULL, NULL, 0, NULL, NULL, NULL, FALSE, TRUE, 'active', 'Goods end here on a delivery', '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, 'system', NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000000LOC0003', 'Inter-warehouse Transit', 'Inter-warehouse Transit', 'transit', NULL, NULL, NULL, 0, NULL, NULL, NULL, FALSE, TRUE, 'active', 'Holds stock that has left one warehouse but not yet arrived at the next', '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, 'system', NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000000LOC0004', 'Scrapped Goods', 'Scrapped Goods', 'scrap', NULL, NULL, NULL, 0, NULL, NULL, NULL, FALSE, TRUE, 'active', 'Destination of every scrap document', '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, 'system', NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000000LOC0005', 'Inventory Adjustment', 'Inventory Adjustment', 'inventory_loss', NULL, NULL, NULL, 0, NULL, NULL, NULL, FALSE, TRUE, 'active', 'Counterparty for count adjustments; absorbs both gains and losses', '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, 'system', NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000000LOC0006', 'Virtual Production', 'Virtual Production', 'virtual', NULL, NULL, NULL, 0, NULL, NULL, NULL, FALSE, TRUE, 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, 'system', NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),

		-- WH-CENTRAL: three-step in and out, so it has receiving, quality, stock, picking, packing
