		('01K5INV000000000000LOC0010', 'Central DC', 'Central DC', 'internal', 'storage', '01K5INV00000000000WH000001', NULL, 0, 'LOC-CEN-STOCK', '01K5INV0000000000STOR00001', 'fifo', TRUE, TRUE, 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, 'commerce/inventory_warehouse', '01K5INV00000000000WH000001', (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000000LOC0011', 'Receiving Dock', 'Central DC / Receiving Dock', 'internal', 'receiving', '01K5INV00000000000WH000001', '01K5INV000000000000LOC0010', 1, 'LOC-CEN-IN', NULL, NULL, FALSE, TRUE, 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, NULL, NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000000LOC0012', 'Quality Control', 'Central DC / Quality Control', 'internal', 'quality', '01K5INV00000000000WH000001', '01K5INV000000000000LOC0010', 1, 'LOC-CEN-QC', NULL, NULL, FALSE, TRUE, 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, NULL, NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000000LOC0014', 'Aisle A Bin 01', 'Central DC / Aisle A Bin 01', 'internal', 'storage', '01K5INV00000000000WH000001', '01K5INV000000000000LOC0010', 1, 'LOC-CEN-A01', '01K5INV0000000000STOR00001', 'fifo', FALSE, FALSE, 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, NULL, NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
