		('01K5INV000000000000LOC0016', 'Chilled Bay', 'Central DC / Chilled Bay', 'internal', 'storage', '01K5INV00000000000WH000001', '01K5INV000000000000LOC0010', 1, 'LOC-CEN-CHILL', '01K5INV0000000000STOR00002', 'fefo', FALSE, FALSE, 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, NULL, NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000000LOC0017', 'Bulk Pallet Floor', 'Central DC / Bulk Pallet Floor', 'internal', 'storage', '01K5INV00000000000WH000001', '01K5INV000000000000LOC0010', 1, 'LOC-CEN-BULK', '01K5INV0000000000STOR00003', 'lifo', FALSE, FALSE, 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, NULL, NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000000LOC0018', 'High-value Cage', 'Central DC / High-value Cage', 'internal', 'storage', '01K5INV00000000000WH000001', '01K5INV000000000000LOC0010', 1, 'LOC-CEN-CAGE', '01K5INV0000000000STOR00004', 'closest', FALSE, FALSE, 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, NULL, NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000000LOC0019', 'Picking Zone', 'Central DC / Picking Zone', 'internal', 'picking', '01K5INV00000000000WH000001', '01K5INV000000000000LOC0010', 1, 'LOC-CEN-PICK', NULL, 'least_packages', FALSE, TRUE, 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, NULL, NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
