		('01K5INV000000000000LOC0021', 'Shipping Dock', 'Central DC / Shipping Dock', 'internal', 'output', '01K5INV00000000000WH000001', '01K5INV000000000000LOC0010', 1, 'LOC-CEN-OUT', NULL, NULL, FALSE, TRUE, 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, NULL, NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
