		('01K5INV000000000000LOC0033', 'North Aisle B Bin 01', 'North Warehouse / North Aisle B Bin 01', 'internal', 'storage', '01K5INV00000000000WH000002', '01K5INV000000000000LOC0030', 1, 'LOC-NOR-B01', '01K5INV0000000000STOR00001', 'fifo', FALSE, FALSE, 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, NULL, NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
