		('01K5INV000000000000LOC0040', 'South Warehouse', 'South Warehouse', 'internal', 'storage', '01K5INV00000000000WH000003', NULL, 0, 'LOC-SOU-STOCK', '01K5INV0000000000STOR00001', 'fifo', TRUE, TRUE, 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, 'commerce/inventory_warehouse', '01K5INV00000000000WH000003', (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000000LOC0042', 'South Aisle C Bin 01', 'South Warehouse / South Aisle C Bin 01', 'internal', 'storage', '01K5INV00000000000WH000003', '01K5INV000000000000LOC0040', 1, 'LOC-SOU-C01', '01K5INV0000000000STOR00001', 'fifo', FALSE, FALSE, 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, NULL, NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01K5INV000000000000LOC0043', 'South Picking', 'South Warehouse / South Picking', 'internal', 'picking', '01K5INV00000000000WH000003', '01K5INV000000000000LOC0040', 1, 'LOC-SOU-PICK', NULL, 'fifo', FALSE, TRUE, 'active', NULL, '01JWNY20G23KD4RV5VWYABQYHD', FALSE, NOW(), NULL, NULL, NULL, (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
