		-- A warehouse holds a RESTRICT FK to its root location, so it is written with none and pointed
		-- at the root once the root exists.
		UPDATE "inventory_warehouses" w
		SET "root_location_id" = l."id"
		FROM "inventory_locations" l
		WHERE l."managed_by_type" = 'commerce/inventory_warehouse'
			AND l."managed_by_id" = w."id"
			AND w."root_location_id" IS NULL;


