		-- Base sales prices, carried over from the inventory_product_prices demo rows that the
		-- product-pricing change request removed. Each template takes the LOWEST approved price its
		-- variants had: base_sales_price is the template's reference price, and what a particular
		-- variant adds to it belongs in sales_price_extra rather than in a second base price.
		--
		-- The old rows' other dimensions have no home here and are deliberately dropped: draft and
		-- expired rows were a workflow this CR replaces with is_archived, and the effective dates
		-- were a validity window that now belongs to a Sales pricelist rule.
		UPDATE "inventory_product_templates" SET "base_sales_price" = 15000 WHERE "id" = '01K5INV0000000TMPL00000001';
		UPDATE "inventory_product_templates" SET "base_sales_price" = 8000 WHERE "id" = '01K5INV0000000TMPL00000002';
		UPDATE "inventory_product_templates" SET "base_sales_price" = 12000 WHERE "id" = '01K5INV0000000TMPL00000003';
		UPDATE "inventory_product_templates" SET "base_sales_price" = 95000 WHERE "id" = '01K5INV0000000TMPL00000004';
		UPDATE "inventory_product_templates" SET "base_sales_price" = 9500 WHERE "id" = '01K5INV0000000TMPL00000005';
		UPDATE "inventory_product_templates" SET "base_sales_price" = 30000 WHERE "id" = '01K5INV0000000TMPL00000007';
		UPDATE "inventory_product_templates" SET "base_sales_price" = 120000 WHERE "id" = '01K5INV0000000TMPL00000010';

