		ON CONFLICT ("id") DO NOTHING;

		-- Stock quants: on-hand stock per (variant, location, lot, package, owner). The unique key
		-- includes lot_ref / package_ref / owner_ref, all NOT NULL, so unused slots carry the empty
		-- string. reserved_quantity is non-zero only where an assigned move is holding stock.
		--
		-- The counting fields cover the whole cycle-count lifecycle:
		--   next_count_date in the past          -> a count is due (QUANT0001, 0004, 0009, 0012)
		--   next_count_date in the future        -> counted recently, nothing due
		--   count_quantity_set = TRUE            -> a counter has entered a figure not yet applied
		--   counted_quantity <> on_hand_quantity -> a discrepancy awaiting an adjustment
		--   count_snapshot_quantity              -> the on-hand figure when the count sheet issued
